<?php
declare(strict_types=1);
require_once __DIR__.'/../../semana-02/ejemplo-srp/despues/IdentityWorkflow.php';
require_once __DIR__.'/../../semana-02/ejemplo-srp/despues/InMemoryAdapters.php';
function eq(mixed $e,mixed $a):void{if($e!==$a)throw new RuntimeException('Resultado inesperado');}
function now():DateTimeImmutable{return new DateTimeImmutable('2026-10-27T12:00:00-06:00');}
function infra():InMemoryIdentityInfrastructure{$i=new InMemoryIdentityInfrastructure(now());$i->addTenant('H1');$i->addTenant('H2');$i->authorizeAdmin('ADMIN','H1');$i->allowRole('ADMIN','H1','TECH');return $i;}
function registration(InMemoryIdentityInfrastructure $i,?TenantDirectory $t=null):RegisterTenantUser{return new RegisterTenantUser($t??$i,$i,$i,$i,$i,$i);}
function command(string $admin='ADMIN',string $tenant='H1',string $role='TECH'):RegistrationCommand{return new RegistrationCommand($admin,$tenant,new NewIdentity('DEMO-U','Persona demo'),$role);}
function seeded():InMemoryIdentityInfrastructure{$i=infra();eq(RegistrationStatus::REGISTERED,registration($i)->execute(command())->status);$i->addCredentials('DEMO-U','Demo-secret-only-17');return $i;}
function login(InMemoryIdentityInfrastructure $i,?SessionTokenIssuer $issuer=null):AuthenticateTenantUser{return new AuthenticateTenantUser($i,$i,$i,$i,$issuer??$i,$i);}
final class DirectorySpy implements TenantDirectory{public int $calls=0;public function isActive(string $id):bool{$this->calls++;return true;}}
final class IssuerSpy implements SessionTokenIssuer{public int $calls=0;public function issue(string $s,string $t,DateTimeImmutable $e):?SessionToken{$this->calls++;return new SessionToken($s,$t,'JTI-DEMO',$e);}}
$tests=[];
$tests['U01 membresia limites inclusivo inicio exclusivo fin']=function(){foreach([[now(),null,true],[now()->modify('+1 second'),null,false],[now()->modify('-1 hour'),now(),false],[now()->modify('-1 hour'),now()->modify('+1 second'),true]] as [$from,$to,$expected])eq($expected,(new TenantMembership('U','H1','TECH',MembershipStatus::ACTIVE,$from,$to))->isValidAt(now()));eq(false,(new TenantMembership('U','H1','TECH',MembershipStatus::INACTIVE,now()))->isValidAt(now()));};
$tests['U02 credencial correcta incorrecta desconocida']=function(){$i=infra();$i->addCredentials('DEMO-U','Demo-secret-only-17');eq(true,$i->verify('DEMO-U','Demo-secret-only-17'));eq(false,$i->verify('DEMO-U','incorrecta'));eq(false,$i->verify('NO-EXISTE','incorrecta'));};
$tests['U03 sesion limite exp exacto y futuro']=function(){$i=infra();$check=new CheckSessionAccess($i,$i);eq(SessionAccessStatus::EXPIRED,$check->execute(new SessionToken('U','H1','J',now()),'H1'));eq(SessionAccessStatus::ALLOWED,$check->execute(new SessionToken('U','H1','J',now()->modify('+1 second')),'H1'));};
$tests['U04 revocacion aislada por tenant y jti']=function(){$i=infra();$i->revoke('H1','J',now()->modify('+15 minutes'));eq(true,$i->isRevoked('H1','J'));eq(false,$i->isRevoked('H2','J'));eq(false,$i->isRevoked('H1','OTRO'));};
$tests['W01 alta invalida corta antes de dependencias']=function(){$i=infra();$spy=new DirectorySpy();eq(RegistrationStatus::INVALID_INPUT,registration($i,$spy)->execute(command(' '))->status);eq(0,$spy->calls);eq(0,$i->identityCount());};
$tests['W02 credencial invalida no emite token']=function(){$i=seeded();$spy=new IssuerSpy();eq(AuthenticationStatus::FAILED,login($i,$spy)->execute(new AuthenticationCommand('H1','DEMO-U','incorrecta'))->status);eq(0,$spy->calls);eq(AuthenticationStatus::AUTHENTICATED,login($i,$spy)->execute(new AuthenticationCommand('H1','DEMO-U','Demo-secret-only-17'))->status);eq(1,$spy->calls);};
$tests['W03 falla de alta no deja identidad ni membresia']=function(){$i=infra();$i->failNextRegistration();eq(RegistrationStatus::PERSISTENCE_FAILURE,registration($i)->execute(command())->status);eq(0,$i->identityCount());eq(0,$i->membershipCount());};
$tests['B01 alta permitida y membresia duplicada']=function(){$i=infra();$u=registration($i);eq(RegistrationStatus::REGISTERED,$u->execute(command())->status);eq(RegistrationStatus::DUPLICATE_MEMBERSHIP,$u->execute(command())->status);eq(1,$i->identityCount());eq(1,$i->membershipCount());};
$tests['B02 administrador rol y tenant denegados']=function(){$i=infra();$u=registration($i);eq(RegistrationStatus::FORBIDDEN,$u->execute(command('OTRO'))->status);eq(RegistrationStatus::FORBIDDEN,$u->execute(command(role:'SUPERADMIN'))->status);eq(RegistrationStatus::FORBIDDEN,$u->execute(command(tenant:'H2'))->status);$i->addTenant('H1',false);eq(RegistrationStatus::TENANT_UNAVAILABLE,$u->execute(command())->status);eq(0,$i->identityCount());};
$tests['B03 login contextual y aislamiento sin membresia cruzada']=function(){$i=seeded();$u=login($i);$o=$u->execute(new AuthenticationCommand('H1','DEMO-U','Demo-secret-only-17'));eq(AuthenticationStatus::AUTHENTICATED,$o->status);eq('H1',$o->token->tenantId);eq('DEMO-U',$o->token->subject);eq(now()->modify('+15 minutes')->format(DATE_ATOM),$o->token->expiresAt->format(DATE_ATOM));eq(AuthenticationStatus::FAILED,$u->execute(new AuthenticationCommand('H2','DEMO-U','Demo-secret-only-17'))->status);};
$tests['B04 errores genericos sin token']=function(){$i=seeded();$u=login($i);foreach([new AuthenticationCommand('H1','DEMO-U','incorrecta'),new AuthenticationCommand('H1','NO-EXISTE','incorrecta')] as $c){$o=$u->execute($c);eq(AuthenticationStatus::FAILED,$o->status);eq(null,$o->token);}$i->addIdentity(new UserIdentity('DEMO-U','Demo',IdentityStatus::INACTIVE));eq(AuthenticationStatus::FAILED,$u->execute(new AuthenticationCommand('H1','DEMO-U','Demo-secret-only-17'))->status);};
$tests['B05 logout revocado y acceso tenant ajeno rechazados']=function(){$i=seeded();$token=login($i)->execute(new AuthenticationCommand('H1','DEMO-U','Demo-secret-only-17'))->token;$check=new CheckSessionAccess($i,$i);eq(SessionAccessStatus::INVALID,$check->execute($token,'H2'));eq(RevocationStatus::REVOKED,(new RevokeCurrentSession($i,$i))->execute($token));eq(SessionAccessStatus::REVOKED,$check->execute($token,'H1'));};
$tests['B06 falla revocacion no confirma cierre']=function(){$i=seeded();$token=login($i)->execute(new AuthenticationCommand('H1','DEMO-U','Demo-secret-only-17'))->token;$i->failNextRevocation();eq(RevocationStatus::STORAGE_UNAVAILABLE,(new RevokeCurrentSession($i,$i))->execute($token));eq(SessionAccessStatus::ALLOWED,(new CheckSessionAccess($i,$i))->execute($token,'H1'));};
$tests['B07 membresia inactiva y expirada bloquean login']=function(){$i=seeded();foreach([new TenantMembership('DEMO-U','H1','TECH',MembershipStatus::INACTIVE,now()),new TenantMembership('DEMO-U','H1','TECH',MembershipStatus::ACTIVE,now()->modify('-1 day'),now())] as $m){$i->addMembership($m);eq(AuthenticationStatus::FAILED,login($i)->execute(new AuthenticationCommand('H1','DEMO-U','Demo-secret-only-17'))->status);}};
if(in_array('--defectos',$argv,true)){$tests=[];
$tests['D01 sesion con campos solo blancos aceptada']=function(){$i=infra();$token=new SessionToken(' ','H1',' ',now()->modify('+1 minute'));eq(SessionAccessStatus::ALLOWED,(new CheckSessionAccess($i,$i))->execute($token,'H1'));eq(RevocationStatus::INVALID_TOKEN,(new RevokeCurrentSession($i,$i))->execute($token));};
$tests['D02 emisor devuelve token de otro tenant y login informa exito']=function(){$i=seeded();$bad=new class implements SessionTokenIssuer{public function issue(string $s,string $t,DateTimeImmutable $e):?SessionToken{return new SessionToken($s,'H2','J-DEMO',$e);}};$o=login($i,$bad)->execute(new AuthenticationCommand('H1','DEMO-U','Demo-secret-only-17'));eq(AuthenticationStatus::AUTHENTICATED,$o->status);eq('H2',$o->token->tenantId);};
echo "REPRODUCCION: PASS indica defecto observado, no corregido.\n";}
$failed=0;foreach($tests as $id=>$test){try{$test();echo "PASS $id\n";}catch(Throwable $e){$failed++;echo "FAIL $id: {$e->getMessage()}\n";}}echo count($tests)." casos, $failed fallidos.\n";exit($failed===0?0:1);